   346			if group.Matcher == nil {
   347				groups[i].Hooks = append(groups[i].Hooks, entry)
   348				return groups
   349			}
   350		}
   351		return append(groups, MatcherGroup{
   352			Matcher: nil,
   353			Hooks:   []HookEntry{entry},
   354		})
   355	}
